// Helper to lookup bitmap by pet type
inline const uint16_t* getPetBitmap(DeskPetType type) {
    static const uint16_t* const PET_TABLE[4] = {
        pet_tomato_bmp,
        pet_cat_bmp,
        pet_shiba_bmp,
        pet_capybara_bmp
    };
    if ((uint8_t)type >= 4) type = PET_TOMATO;
    return PET_TABLE[(uint8_t)type];
}

